const alvo = [
  'atomdigital.com.br', 'expodonto.com.br', 'orcaapp.com.br', 'clickguincho.com.br',
  'drpedromaciel.com.br', 'astronautasfilmes.com.br', 'institutosiguimitanigute.com.br',
  'aquasampa.com.br', 'drfredericoxavier.com.br', 'aconchegoidosos.com.br',
  'primemateriaiseletricos.com.br', 'salazardigital.com.br', 'griffepneus.com.br', 'tetraconind.com.br'
];
const sites = ($input.first().json.siteEntry || []).map(s => s.siteUrl);
const limpa = u => u.replace(/^sc-domain:/, '').replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
const fmt = d => d.toISOString().slice(0, 10);
const dias = (d, n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x; };
// GSC tem ~3 dias de atraso: janela atual = 28 dias terminando 3 dias atrás
const fimAtual = dias(new Date(), -3);
const iniAtual = dias(fimAtual, -27);
const fimAnt = dias(iniAtual, -1);
const iniAnt = dias(fimAnt, -27);
const periodos = { atual: [fmt(iniAtual), fmt(fimAtual)], anterior: [fmt(iniAnt), fmt(fimAnt)] };
const faltando = [];
const out = [];
for (const dom of alvo) {
  const cands = sites.filter(u => limpa(u) === dom);
  if (!cands.length) { faltando.push(dom); continue; }
  const siteUrl = cands.find(u => u.startsWith('sc-domain:')) || cands[0];
  for (const [periodo, [ini, fim]] of Object.entries(periodos)) {
    for (const dim of ['query', 'page']) {
      out.push({ json: { dominio: dom, siteUrl, periodo, dimensao: dim,
        body: { startDate: ini, endDate: fim, dimensions: [dim], rowLimit: dim === 'query' ? 1000 : 250, dataState: 'final' } } });
    }
  }
}
if (out.length) { out[0].json.faltando = faltando; out[0].json.periodos = periodos; }
return out;

const reqs = $('Montar consultas').all();
const res = $input.all();
const primeiro = reqs[0] ? reqs[0].json : {};
const resultado = {
  geradoEm: new Date().toISOString(),
  periodos: primeiro.periodos || {},
  semPropriedadeNoGSC: primeiro.faltando || [],
  sites: {}
};
res.forEach((r, i) => {
  const idx = (r.pairedItem && typeof r.pairedItem.item === 'number') ? r.pairedItem.item : i;
  const q = (reqs[idx] || reqs[i]).json;
  const s = resultado.sites[q.dominio] = resultado.sites[q.dominio] || { siteUrl: q.siteUrl };
  const chave = q.dimensao + '_' + q.periodo;
  if (r.json.error) { s[chave] = { erro: String(r.json.error.message || r.json.error) }; return; }
  const linhas = r.json.rows || [];
  s[chave] = linhas.map(x => ({
    k: x.keys[0], cliques: x.clicks, impressoes: x.impressions,
    ctr: Math.round(x.ctr * 10000) / 100, posicao: Math.round(x.position * 10) / 10
  }));
  if (!s['totais_' + q.periodo] && q.dimensao === 'page') {
    s['totais_' + q.periodo] = {
      cliques: linhas.reduce((a, x) => a + x.clicks, 0),
      impressoes: linhas.reduce((a, x) => a + x.impressions, 0)
    };
  }
});
const data = new Date().toISOString().slice(0, 10);
return [{ json: { nome: 'gsc-semanal-' + data + '.json', conteudo: JSON.stringify(resultado) } }];
